Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": { "name": "dataset" },
  "width": 500,
  "height": 180,
  "background": null,

  "transform": [
    {
      "calculate": "toNumber(datum.Year) * 4 + toNumber(replace(datum.Quarter, ''Qtr '', ''''))",
      "as": "QuarterSort"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "QuarterSort",
          "as": "MaxQuarterSort"
        }
      ]
    },
    {
      "filter": "datum.QuarterSort >= datum.MaxQuarterSort - 3 && datum.QuarterSort <= datum.MaxQuarterSort"
    },
    {
      "calculate": "toNumber(datum.col_ci_perf_qtly_performance_tier_num)",
      "as": "Tier"
    },
    {
      "calculate": "datum.Tier == 1 ? ''Underperformer'' : datum.Tier == 2 ? ''Performer'' : datum.Tier == 3 ? ''Overperformer'' : ''Unknown''",
      "as": "PerformanceLabel"
    },
    {
      "calculate": "''Q'' + replace(datum.Quarter, ''Qtr '', '''') + '', '' + toString(datum.Year)",
      "as": "QuarterLabel"
    }
  ],

  "layer": [
    {
      "data": {
        "values": [
          { "PerformanceLabel": "Overperformer" },
          { "PerformanceLabel": "Performer" },
          { "PerformanceLabel": "Underperformer" }
        ]
      },
      "mark": {
        "type": "rule",
        "stroke": "#ffffff",
        "strokeWidth": 1,
        "opacity": 0.4
      },
      "encoding": {
        "y": {
          "field": "PerformanceLabel",
          "type": "ordinal",
          "scale": {
            "domain": ["Overperformer", "Performer", "Underperformer"]
          }
        }
      }
    },
    {
      "mark": {
        "type": "circle",
        "filled": true,
        "size": 140
      },
      "encoding": {
        "x": {
          "field": "QuarterLabel",
          "type": "ordinal",
          "sort": {
            "field": "QuarterSort",
            "order": "ascending"
          },
          "title": null,
          "axis": {
            "labelColor": "#ffffff",
            "labelAngle": 0,
            "domain": false,
            "ticks": false
          }
        },
        "y": {
          "field": "PerformanceLabel",
          "type": "ordinal",
          "title": null,
          "scale": {
            "domain": ["Overperformer", "Performer", "Underperformer"]
          },
          "axis": {
            "labelColor": "#ffffff",
            "domain": false,
            "ticks": false
          }
        },
        "color": {
          "field": "PerformanceLabel",
          "type": "nominal",
          "scale": {
            "domain": ["Underperformer", "Performer", "Overperformer"],
            "range": ["#ff2b8a", "#58cfd3", "#22a6a8"]
          },
          "legend": {
            "orient": "bottom",
            "labelColor": "#ffffff",
            "title": null
          }
        },
        "tooltip": [
          { "field": "QuarterLabel", "title": "Quarter" },
          { "field": "PerformanceLabel", "title": "Performance" },
          { "field": "Tier", "title": "Tier" }
        ]
      }
    }
  ],

  "config": {
    "view": { "stroke": null },
    "axis": {
      "labelColor": "#ffffff",
      "titleColor": "#ffffff",
      "grid": false
    },
    "legend": {
      "labelColor": "#ffffff",
      "titleColor": "#ffffff"
    }
  }
}'
